            gap: clamp(0.5rem, 1.5vw, 1rem);
        }
        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }
        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           THEME: Deep Tech Dark with Cyan/Magenta Accents
           =========================================== */
        :root {
            --bg-primary: #0a0a12;
            --bg-secondary: #12121f;
            --bg-card: #1a1a2e;
            --text-primary: #f0f0f5;
            --text-secondary: #a0a0b5;
            --accent-cyan: #00d4ff;
            --accent-magenta: #ff2d95;
            --accent-purple: #8b5cf6;
            --accent-green: #22c55e;
            --border-color: rgba(255,255,255,0.08);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Satoshi', sans-serif;
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.6;
        }

        h1, h2, h3 {
            font-family: 'Cabinet Grotesk', sans-serif;
            font-weight: 700;
        }

        /* === SLIDE 1: TITLE === */
        .slide-title {
            background:
                radial-gradient(ellipse at 30% 20%, rgba(0, 212, 255, 0.15) 0%, transparent 50%),
                radial-gradient(ellipse at 70% 80%, rgba(255, 45, 149, 0.12) 0%, transparent 50%),
                linear-gradient(135deg, var(--bg-primary) 0%, var(--bg-secondary) 100%);
        }

        .slide-title::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-image:
                linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
        }

        .title-content {
            text-align: center;
            position: relative;
            z-index: 1;
        }

        .title-badge {
            display: inline-block;
            padding: clamp(0.3rem, 0.8vw, 0.6rem) clamp(0.8rem, 2vw, 1.5rem);
            background: linear-gradient(135deg, var(--accent-cyan), var(--accent-purple));
            border-radius: 100px;
            font-size: var(--small-size);
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            margin-bottom: var(--content-gap);
            animation: fadeSlideUp 0.8s ease-out both;
        }

        .title-main {
            font-size: var(--title-size);
            background: linear-gradient(135deg, var(--text-primary) 0%, var(--accent-cyan) 50%, var(--text-primary) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            margin-bottom: var(--element-gap);
            animation: fadeSlideUp 0.8s ease-out 0.1s both;
        }

        .title-subtitle {
            font-size: clamp(1rem, 2.5vw, 1.5rem);
            color: var(--text-secondary);
            font-weight: 500;
            animation: fadeSlideUp 0.8s ease-out 0.2s both;
        }

        .title-meta {
            margin-top: var(--content-gap);
            font-size: var(--small-size);
            color: var(--text-secondary);
            animation: fadeSlideUp 0.8s ease-out 0.3s both;
        }

        .title-meta span {
            margin: 0 clamp(0.5rem, 1.5vw, 1rem);
        }

        .title-visual {
            margin-top: clamp(1.5rem, 4vw, 3rem);
            display: flex;
            justify-content: center;
            gap: clamp(1rem, 3vw, 2rem);
            animation: fadeSlideUp 0.8s ease-out 0.4s both;
        }

        .title-visual-box {
            width: clamp(80px, 12vw, 140px);
            height: clamp(60px, 8vw, 100px);
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-direction: column;
            gap: 0.3rem;
        }

        .title-visual-box .icon {
            font-size: clamp(1.2rem, 3vw, 2rem);
        }

        .title-visual-box .label {
            font-size: clamp(0.5rem, 1vw, 0.7rem);
            color: var(--text-secondary);
        }

        .title-visual-box.highlight {
            border-color: var(--accent-cyan);
            box-shadow: 0 0 30px rgba(0, 212, 255, 0.3);
        }

        /* === SLIDE 2: PROBLEM === */
        .slide-problem {
            background: var(--bg-primary);
        }

        .slide-header {
            margin-bottom: var(--content-gap);
        }

        .slide-number {
            font-size: var(--small-size);
            color: var(--accent-cyan);
            font-weight: 700;
            margin-bottom: 0.5rem;
        }

        .slide-title-text {
            font-size: var(--h2-size);
            color: var(--text-primary);
        }

        .problem-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .problem-card {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: clamp(1rem, 2.5vw, 1.5rem);
            position: relative;
            overflow: hidden;
        }

        .problem-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: linear-gradient(90deg, var(--accent-magenta), var(--accent-purple));
        }

        .problem-card h3 {
            font-size: var(--body-size);
            color: var(--text-primary);
            margin-bottom: 0.8rem;
        }

        .problem-card .stat {
            font-size: clamp(1.5rem, 4vw, 2.5rem);
            font-weight: 700;
            color: var(--accent-magenta);
            margin-bottom: 0.3rem;
        }

        .problem-card .desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .problem-card.good::before {
            background: linear-gradient(90deg, var(--accent-green), var(--accent-cyan));
        }

        .problem-card.good .stat {
            color: var(--accent-green);
        }

        /* === SLIDE 3: ARCHITECTURE === */
        .slide-arch {
            background:
                radial-gradient(ellipse at 50% 50%, rgba(139, 92, 246, 0.1) 0%, transparent 70%),
                var(--bg-primary);
        }

        .arch-flow {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: clamp(0.5rem, 1.5vw, 1rem);
            margin-top: var(--content-gap);
            flex-wrap: wrap;
        }

        .arch-step {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 12px;
            padding: clamp(0.8rem, 2vw, 1.2rem) clamp(1rem, 2.5vw, 1.5rem);
            text-align: center;
            min-width: clamp(100px, 15vw, 160px);
        }

        .arch-step-icon {
            font-size: clamp(1.5rem, 3vw, 2rem);
            margin-bottom: 0.5rem;
        }

        .arch-step-name {
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 0.2rem;
        }

        .arch-step-detail {
            font-size: clamp(0.55rem, 0.9vw, 0.7rem);
            color: var(--text-secondary);
        }

        .arch-arrow {
            font-size: clamp(1rem, 2vw, 1.5rem);
            color: var(--accent-cyan);
        }

        .arch-notes {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr));
            gap: var(--element-gap);
            margin-top: var(--content-gap);
        }

        .arch-note {
            display: flex;
            align-items: flex-start;
            gap: 0.5rem;
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .arch-note-icon {
            color: var(--accent-cyan);
            flex-shrink: 0;
        }

        /* === SLIDE 4: COMPUTE ALLOCATION === */
        .slide-compute {
            background: var(--bg-primary);
        }

        .compute-chart {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: clamp(1rem, 3vw, 2rem);
            margin-top: var(--content-gap);
        }

        .chart-title {
            font-size: var(--body-size);
            color: var(--text-secondary);
            margin-bottom: var(--element-gap);
        }

        .bar-group {
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }

        .bar-row {
            display: flex;
            align-items: center;
            gap: clamp(0.5rem, 2vw, 1rem);
        }

        .bar-label {
            font-size: var(--small-size);
            color: var(--text-primary);
            min-width: clamp(120px, 20vw, 200px);
            text-align: right;
        }

        .bar-container {
            flex: 1;
            height: clamp(20px, 4vw, 32px);
            background: rgba(255,255,255,0.05);
            border-radius: 8px;
            overflow: hidden;
            position: relative;
        }

        .bar-fill {
            height: 100%;
            border-radius: 8px;
            display: flex;
            align-items: center;
            padding-left: 0.5rem;
            font-size: var(--small-size);
            font-weight: 600;
            color: var(--bg-primary);
            transition: width 1s var(--ease-out-expo);
        }

        .bar-fill.cyan { background: linear-gradient(90deg, var(--accent-cyan), #00a8cc); }
        .bar-fill.magenta { background: linear-gradient(90deg, var(--accent-magenta), #cc1d6e); }
        .bar-fill.green { background: linear-gradient(90deg, var(--accent-green), #16a34a); }
        .bar-fill.purple { background: linear-gradient(90deg, var(--accent-purple), #6d28d9); }

        .bar-value {
            font-size: var(--small-size);
            color: var(--text-secondary);
            min-width: clamp(50px, 8vw, 80px);
        }

        .compute-insight {
            background: linear-gradient(135deg, rgba(0, 212, 255, 0.1), rgba(139, 92, 246, 0.1));
            border: 1px solid var(--accent-cyan);
            border-radius: 12px;
            padding: clamp(0.8rem, 2vw, 1.2rem);
            margin-top: var(--content-gap);
            font-size: var(--small-size);
            color: var(--text-primary);
        }

        .compute-insight strong {
            color: var(--accent-cyan);
        }

        /* === SLIDE 5: TOKEN COMPRESSION === */
        .slide-compression {
            background:
                radial-gradient(ellipse at 30% 70%, rgba(34, 197, 94, 0.1) 0%, transparent 50%),
                var(--bg-primary);
        }

        .compression-layout {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        @media (max-width: 768px) {
            .compression-layout { grid-template-columns: 1fr; }
        }

        .pixel-shuffle-diagram {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: clamp(1rem, 2.5vw, 1.5rem);
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .diagram-title {
            font-size: var(--body-size);
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: var(--content-gap);
        }

        .pixel-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 4px;
            margin-bottom: var(--element-gap);
        }

        .pixel-grid.sparse {
            grid-template-columns: repeat(2, 1fr);
        }

        .pixel {
            width: clamp(24px, 4vw, 40px);
            height: clamp(24px, 4vw, 40px);
            background: var(--accent-cyan);
            border-radius: 4px;
            opacity: 0.7;
        }

        .pixel.compressed {
            background: var(--accent-purple);
        }

        .pixel.arrow-down {
            background: transparent;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: clamp(1rem, 2vw, 1.5rem);
            color: var(--text-secondary);
        }

        .diagram-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            text-align: center;
        }

        .compression-table {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: clamp(1rem, 2.5vw, 1.5rem);
        }

        .comp-table-title {
            font-size: var(--body-size);
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: var(--element-gap);
        }

        table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--small-size);
        }

        th, td {
            padding: clamp(0.4rem, 1vw, 0.7rem);
            text-align: left;
            border-bottom: 1px solid var(--border-color);
        }

        th {
            color: var(--text-secondary);
            font-weight: 500;
        }

        td {
            color: var(--text-primary);
        }

        td.highlight {
            color: var(--accent-green);
            font-weight: 600;
        }

        /* === SLIDE 6: CONTEXT LENGTH === */
        .slide-context {
            background: var(--bg-primary);
        }

        .context-flow {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: clamp(1rem, 3vw, 2rem);
            margin: var(--content-gap) 0;
            flex-wrap: wrap;
        }

        .context-box {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 12px;
            padding: clamp(1rem, 2.5vw, 1.5rem);
            text-align: center;
            min-width: clamp(100px, 15vw, 140px);
        }

        .context-box.highlight {
            border-color: var(--accent-green);
            box-shadow: 0 0 20px rgba(34, 197, 94, 0.2);
        }

        .context-val {
            font-size: clamp(1.5rem, 4vw, 2.5rem);
            font-weight: 700;
            color: var(--accent-cyan);
        }

        .context-val.small { color: var(--text-secondary); }

        .context-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .context-arrow {
            font-size: clamp(1.5rem, 3vw, 2rem);
            color: var(--accent-green);
        }

        .context-specs {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr));
            gap: var(--element-gap);
            margin-top: var(--content-gap);
        }

        .spec-item {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 10px;
            padding: clamp(0.8rem, 2vw, 1rem);
            display: flex;
            align-items: center;
            gap: 0.8rem;
        }

        .spec-icon {
            font-size: clamp(1.2rem, 2.5vw, 1.5rem);
        }

        .spec-text {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .spec-text strong {
            color: var(--text-primary);
            display: block;
        }

        /* === SLIDE 7: BENCHMARK === */
        .slide-benchmark {
            background:
                radial-gradient(ellipse at 80% 20%, rgba(0, 212, 255, 0.08) 0%, transparent 50%),
                var(--bg-primary);
        }

        .benchmark-table-wrap {
            overflow-x: auto;
            margin-top: var(--content-gap);
        }

        .benchmark-table {
            width: 100%;
            border-collapse: collapse;
            font-size: var(--small-size);
            min-width: 600px;
        }

        .benchmark-table th {
            background: var(--bg-card);
            padding: clamp(0.5rem, 1.2vw, 0.8rem);
            text-align: left;
            color: var(--text-secondary);
            font-weight: 600;
            border-bottom: 2px solid var(--border-color);
        }

        .benchmark-table td {
            padding: clamp(0.4rem, 1vw, 0.6rem);
            border-bottom: 1px solid var(--border-color);
            color: var(--text-primary);
        }

        .benchmark-table tr:hover td {
            background: rgba(255,255,255,0.02);
        }

        .score { font-weight: 600; }
        .score.best { color: var(--accent-green); }
        .score.good { color: var(--accent-cyan); }

        .ram-bar {
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .ram-fill {
            height: 8px;
            background: var(--accent-magenta);
            border-radius: 4px;
            min-width: 4px;
        }

        .ram-text {
            font-size: clamp(0.55rem, 0.8vw, 0.7rem);
            color: var(--text-secondary);
        }

        .avg-row {
            background: rgba(0, 212, 255, 0.1) !important;
            font-weight: 700;
        }

        .avg-row td {
            color: var(--accent-cyan) !important;
        }

        /* === SLIDE 8: ON-DEVICE === */
        .slide-ondevice {
            background: var(--bg-primary);
        }

        .device-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 180px), 1fr));
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .device-card {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: clamp(1rem, 2.5vw, 1.5rem);
            text-align: center;
        }

        .device-icon {
            font-size: clamp(2rem, 5vw, 3rem);
            margin-bottom: 0.5rem;
        }

        .device-name {
            font-size: var(--body-size);
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 0.3rem;
        }

        .device-ram {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-bottom: var(--element-gap);
        }

        .device-stat {
            font-size: clamp(1.5rem, 4vw, 2rem);
            font-weight: 700;
            color: var(--accent-green);
        }

        .device-stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .ondevice-highlight {
            background: linear-gradient(135deg, rgba(34, 197, 94, 0.15), rgba(0, 212, 255, 0.1));
            border: 1px solid var(--accent-green);
            border-radius: 12px;
            padding: clamp(1rem, 2.5vw, 1.5rem);
            margin-top: var(--content-gap);
            text-align: center;
        }

        .ondevice-highlight .big {
            font-size: clamp(2rem, 5vw, 3rem);
            font-weight: 700;
            color: var(--accent-green);
        }

        .ondevice-highlight .label {
            font-size: var(--body-size);
            color: var(--text-secondary);
        }

        /* === SLIDE 9: TAKEAWAYS === */
        .slide-takeaways {
            background:
                radial-gradient(ellipse at 20% 80%, rgba(0, 212, 255, 0.12) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(139, 92, 246, 0.12) 0%, transparent 50%),
                var(--bg-primary);
        }

        .takeaway-list {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
            gap: var(--element-gap);
            margin-top: var(--content-gap);
        }

        .takeaway-item {
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 12px;
            padding: clamp(1rem, 2.5vw, 1.5rem);
            display: flex;
            gap: 1rem;
            align-items: flex-start;
            transition: transform 0.3s ease, border-color 0.3s ease;
        }

        .takeaway-item:hover {
            transform: translateY(-4px);
            border-color: var(--accent-cyan);
        }

        .takeaway-num {
            width: clamp(28px, 4vw, 36px);
            height: clamp(28px, 4vw, 36px);
            background: linear-gradient(135deg, var(--accent-cyan), var(--accent-purple));
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: var(--body-size);
            font-weight: 700;
            color: var(--bg-primary);
            flex-shrink: 0;
        }

        .takeaway-text {
            font-size: var(--body-size);
            color: var(--text-primary);
            line-height: 1.5;
        }

        .takeaway-text strong {
            color: var(--accent-cyan);
        }

        .closing {
            text-align: center;
            margin-top: var(--content-gap);
            padding: clamp(1.5rem, 4vw, 2.5rem);
            background: linear-gradient(135deg, rgba(0, 212, 255, 0.1), rgba(255, 45, 149, 0.1));
            border-radius: 16px;
        }

        .closing-text {
            font-size: var(--h3-size);
            color: var(--text-primary);
            font-weight: 600;
        }

        .closing-sub {
            font-size: var(--body-size);
            color: var(--text-secondary);
            margin-top: 0.5rem;
        }

        /* === NAV === */
        .nav-dots {
            position: fixed;
            right: clamp(1rem, 2vw, 2rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 100;
        }

        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: rgba(255,255,255,0.2);
